INSERT INTO anime (id, title, title_jp, description, poster, backdrop, score, year, status, type, genres) VALUES
(1, 'Sparks of Tomorrow', 'ニジュッセイキ デンキ モクロク エウレカ エヴリカ', 'In a world where humans and mysterious beings coexist, a group of young pilots discover the truth about their world and themselves.', 'https://intocdn.top/wp-content/uploads/2026/07/9H6s2KJSDGZ9PohHZFFUoh1cUUr-360x480.jpg', 'https://intocdn.top/wp-content/uploads/2026/07/eImcA39cNfJzCqczMEQT5FjSlPy.jpg', 8.4, 2026, 'Finished', 'TV', '["Action","Adventure","Sci-Fi"]'),
(2, 'Black Torch', 'ブラックトーチ', 'A young ninja bonds with a mysterious creature to fight dark forces threatening the world.', 'https://intocdn.top/wp-content/uploads/2026/07/blacktorch2-360x480.png', 'https://intocdn.top/wp-content/uploads/2026/07/ceirDIa8QgeeiFKFnLcQpfAH5V7.jpg', 8.2, 2026, 'Finished', 'TV', '["Action","Supernatural","Fantasy"]'),
(3, 'Kaiju Girl Caramelise', 'オトメ カイジュウ キャラメリゼ', 'A shy high school girl discovers she transforms into a giant kaiju whenever she gets excited, especially around her crush.', 'https://intocdn.top/wp-content/uploads/2026/07/zO0vipu5gWi4qV0ARhFkCJWLZDJ-360x480.jpg', 'https://intocdn.top/wp-content/uploads/2026/07/vvbIW2xspYigrgTHTmTSzVDgfKl.jpg', 8.0, 2026, 'Airing', 'TV', '["Romance","Comedy","Supernatural"]'),
(4, 'Dandadan', 'ダンダダン', 'A story about a high school girl who believes in ghosts and a boy who believes in aliens.', 'https://intocdn.top/wp-content/uploads/2024/12/ryefC0mqOSzpyTgIS2suZts4Z7H-360x480.jpg', 'https://intocdn.top/wp-content/uploads/2024/11/jlbUx0aHJupDVDlCo0R7UxSaUUd.jpg', 8.6, 2024, 'Finished', 'TV', '["Action","Comedy","Supernatural"]'),
(5, 'Love Unseen Beneath the Clear Night Sky', '透明な夜に駆ける君', 'A touching romance about a girl who can see things others cannot, and a boy who is invisible to the world.', 'https://intocdn.top/wp-content/uploads/2026/07/Love-Unseen-Beneath-the-Clear-Night-Sky-visual-360x480.jpg', 'https://intocdn.top/wp-content/uploads/2026/07/9MkO2Mx43V2znUzRNHjPRkLBZgk.jpg', 8.3, 2026, 'Finished', 'TV', '["Romance","Drama","Supernatural"]'),
(6, 'Tomb Raider King', '도굴왕', 'A legendary tomb raider is reborn with the power to steal the abilities of ancient relics.', 'https://intocdn.top/wp-content/uploads/2026/07/wK1SL5EUJ6Bq2UhDCRtT1FA1HdN.jpg', 'https://intocdn.top/wp-content/uploads/2026/07/xDW6cor12UD0b2IqboQWnrIn0UO-360x480.jpg', 8.1, 2026, 'Finished', 'TV', '["Action","Adventure","Fantasy"]');
